PRAGMA foreign_keys = ON;

-- A team member who reads and annotates runs.
CREATE TABLE users (
  id INTEGER PRIMARY KEY,
  -- Sign-in name, one per member
  email TEXT NOT NULL,
  name TEXT NOT NULL,
  -- When the row was stored, by the database clock
  created_at TIMESTAMP NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);
CREATE UNIQUE INDEX idx_users_email ON users (email);

-- The machine a run measured on, as perfsweep.Info reports it.
CREATE TABLE machines (
  id INTEGER PRIMARY KEY,
  -- The processor's model name
  cpu TEXT NOT NULL,
  -- Logical CPUs the Go runtime sees
  cores INTEGER NOT NULL,
  memory_gb REAL NOT NULL,
  -- The system and its version, kernel included
  os TEXT NOT NULL,
  arch TEXT NOT NULL,
  -- runtime.Version() of the measuring binary
  go TEXT NOT NULL,
  -- When the row was stored, by the database clock
  created_at TIMESTAMP NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);
CREATE UNIQUE INDEX idx_machines_cpu_cores_memory_gb_os_arch_go ON machines (cpu, cores, memory_gb, os, arch, go);

-- A label a run can carry, such as "v0.3" or an experiment.
CREATE TABLE tags (
  slug TEXT PRIMARY KEY NOT NULL,
  name TEXT NOT NULL
);
CREATE UNIQUE INDEX idx_tags_name_ci ON tags ((lower(name)));

-- One collection run: the sweep, the keystroke benchmark and the
-- latency samples of one commit on one machine. Its id is never reused,
-- since exported reports cite it.
CREATE TABLE runs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  -- The measured commit, lower-case hex
  "commit" TEXT NOT NULL,
  -- The tree had uncommitted changes
  dirty INTEGER NOT NULL DEFAULT 0,
  machine_id INTEGER NOT NULL,
  tag TEXT,
  -- The run this one is compared against
  baseline_id INTEGER,
  note TEXT,
  -- When the row was stored, by the database clock
  created_at TIMESTAMP NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  FOREIGN KEY (machine_id) REFERENCES machines (id) ON DELETE CASCADE,
  FOREIGN KEY (tag) REFERENCES tags (slug) ON DELETE SET NULL ON UPDATE CASCADE,
  FOREIGN KEY (baseline_id) REFERENCES runs (id) ON DELETE SET NULL
);
CREATE INDEX idx_runs_commit ON runs ("commit");

-- The load phase of the sweep at one size.
CREATE TABLE ms_load (
  run_id INTEGER NOT NULL,
  -- Tables in the generated stress project
  tables INTEGER NOT NULL,
  -- Best wall time over the repetitions
  wall_ms REAL NOT NULL,
  -- Bytes allocated by one run, in MiB
  alloc_mb REAL NOT NULL,
  -- Heap in use right after the run, in MiB
  heap_mb REAL NOT NULL,
  -- Allocations by one run
  allocs INTEGER NOT NULL,
  -- Bytes emitted, generate only, in MiB
  output_mb REAL NOT NULL DEFAULT 0,
  -- Size of the project's schema.volt, in KiB
  source_kb REAL NOT NULL,
  PRIMARY KEY (run_id, tables),
  FOREIGN KEY (run_id) REFERENCES runs (id) ON DELETE CASCADE
);
CREATE INDEX idx_ms_load_tables_run_id ON ms_load (tables, run_id);

