-- The language server's keystroke benchmark at one size.
CREATE TABLE keystrokes (
  run_id INTEGER NOT NULL,
  tables INTEGER NOT NULL,
  ms_per_op REAL NOT NULL,
  mb_per_op REAL NOT NULL,
  allocs_per_op INTEGER NOT NULL,
  PRIMARY KEY (run_id, tables),
  FOREIGN KEY (run_id) REFERENCES runs (id) ON DELETE CASCADE
);

-- A commit of Volt's history whose lines were counted.
CREATE TABLE commits (
  sha TEXT PRIMARY KEY NOT NULL,
  subject TEXT NOT NULL,
  author TEXT NOT NULL,
  -- The author date
  at TIMESTAMP NOT NULL
);
CREATE INDEX idx_commits_author_ci ON commits ((lower(author)));

-- The thesis numbers of one fixture at one commit: what Volt writes against what a person writes.
CREATE TABLE line_counts (
  sha TEXT NOT NULL,
  -- The fixture's directory, such as itest/blog
  fixture TEXT NOT NULL,
  -- Lines of .volt files
  volt_lines INTEGER NOT NULL,
  -- Lines of hand-written Go
  hand_lines INTEGER NOT NULL,
  -- Lines of Go carrying the generated marker
  gen_lines INTEGER NOT NULL,
  PRIMARY KEY (sha, fixture),
  FOREIGN KEY (sha) REFERENCES commits (sha) ON DELETE CASCADE
);

-- One timed call of a Voltmeter route by the collector.
CREATE TABLE samples (
  id INTEGER PRIMARY KEY,
  run_id INTEGER NOT NULL,
  route TEXT NOT NULL,
  status INTEGER NOT NULL,
  ms REAL NOT NULL,
  -- Unix milliseconds when the call started
  at INTEGER NOT NULL,
  FOREIGN KEY (run_id) REFERENCES runs (id) ON DELETE CASCADE
);
CREATE INDEX idx_samples_failures ON samples (route, at) WHERE status >= 400;

-- A ceiling on one phase's wall time at one size.
CREATE TABLE budgets (
  id INTEGER PRIMARY KEY,
  phase TEXT NOT NULL,
  tables INTEGER NOT NULL,
  max_ms REAL NOT NULL,
  -- breached once a run went over
  state TEXT NOT NULL DEFAULT 'ok'
);
CREATE UNIQUE INDEX idx_budgets_phase_tables ON budgets (phase, tables);

-- A run that went over a budget.
CREATE TABLE breaches (
  id INTEGER PRIMARY KEY,
  budget_id INTEGER NOT NULL,
  run_id INTEGER NOT NULL,
  wall_ms REAL NOT NULL,
  -- When the row was stored, by the database clock
  created_at TIMESTAMP NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  FOREIGN KEY (budget_id) REFERENCES budgets (id) ON DELETE CASCADE,
  FOREIGN KEY (run_id) REFERENCES runs (id) ON DELETE CASCADE
);

-- A member's arrangement of charts.
CREATE TABLE dashboards (
  id INTEGER PRIMARY KEY,
  owner_id INTEGER NOT NULL,
  name TEXT NOT NULL,
  FOREIGN KEY (owner_id) REFERENCES users (id)
);
CREATE UNIQUE INDEX idx_dashboards_owner_id_name ON dashboards (owner_id, name);

-- One chart on a dashboard.
CREATE TABLE widgets (
  id INTEGER PRIMARY KEY,
  dashboard_id INTEGER NOT NULL,
  position INTEGER NOT NULL,
  phase TEXT NOT NULL,
  tables INTEGER NOT NULL,
  FOREIGN KEY (dashboard_id) REFERENCES dashboards (id) ON DELETE CASCADE
);

